function show() { return this && this.tag; }
var a = { tag: 'A', show: show };
var b = { tag: 'B' };
console.log('1 隐式绑定:', a.show());
console.log('2 显式绑定 call:', show.call(b));
function Ctor(tag) { this.tag = tag; }
var c = new Ctor('C');
console.log('3 new绑定 tag:', c.tag);
var d = {
  tag: 'D',
  fn: function() {
    var inner = () => this.tag;
    return inner();
  }
};
console.log('4 箭头捕获外层this:', d.fn());
console.log('5 默认绑定(非严格):', show());
